<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref,nextTick} from 'vue'
import {APIError,api,allPages,body,type Row} from '../api'
import {confirmAction} from '../confirm'
import {toast} from '../toast'
import SelectField from './SelectField.vue'
import Icon from './Icon.vue'
const rows=ref<Row[]>([]),query=ref(''),status=ref('active'),loading=ref(true),busy=ref(false),error=ref(''),editing=ref<string|null>(null),creating=ref(false),original=ref('')
const form=reactive({name:'',description:'',archived:false})
const filtered=computed(()=>rows.value.filter(r=>(status.value==='all'||(status.value==='archived'?r.archived:!r.archived))&&(`${r.name} ${r.description}`.normalize('NFKC').toLocaleLowerCase().includes(query.value.normalize('NFKC').toLocaleLowerCase().trim()))))
const dirty=computed(()=>(creating.value||editing.value!==null)&&JSON.stringify(form)!==original.value)
async function load(){loading.value=true;error.value='';try{rows.value=await allPages('/admin/tags')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function abandon(){return !dirty.value||await confirmAction('放弃未保存的标签修改？','当前表单内容尚未保存。','放弃修改')}
async function edit(row?:Row){if(busy.value||!await abandon())return;creating.value=!row;editing.value=row?String(row.id):null;Object.assign(form,{name:row?.name||'',description:row?.description||'',archived:!!row?.archived});original.value=JSON.stringify(form);await nextTick();document.querySelector<HTMLInputElement>('[data-tag-edit-name]')?.focus()}
async function cancel(){if(!await abandon())return;creating.value=false;editing.value=null}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await api('/admin/tags'+(creating.value?'':'/'+editing.value),{method:creating.value?'POST':'PATCH',body:body(creating.value?{name:form.name,description:form.description}:{...form})});toast.success(creating.value?'标签已创建。':'标签已更新。');creating.value=false;editing.value=null;await load()}catch(e){if(e instanceof APIError&&e.code==='VALIDATION_FAILED')error.value=e.message;else toast.error((e as Error).message)}finally{busy.value=false}}
function leave(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{void load();window.addEventListener('beforeunload',leave)});onBeforeUnmount(()=>window.removeEventListener('beforeunload',leave))
</script>
<template><section class="content-manager" aria-label="标签管理">
 <div class="manager-toolbar"><div class="manager-search"><label class="sr-only" for="manager-tag-query">搜索标签</label><Icon name="search" :size="18"/><input id="manager-tag-query" v-model="query" :disabled="busy||editing!==null||creating" type="search" placeholder="搜索标签名称或说明"></div><SelectField v-model="status" :disabled="busy||editing!==null||creating" label="标签状态" :options="[{value:'active',label:'使用中'},{value:'archived',label:'已归档'},{value:'all',label:'全部标签'}]"/><button class="primary" :disabled="busy||loading" @click="edit()">新建标签</button></div>
 <p v-if="error" class="notice error" role="alert">{{error}}</p>
 <form v-if="creating" class="tag-inline-editor tag-create" @submit.prevent="save"><h2>新建标签</h2><div class="tag-edit-fields"><label>名称<input v-model="form.name" data-tag-edit-name required maxlength="100" :disabled="busy"></label><label>说明<input v-model="form.description" maxlength="2000" :disabled="busy" placeholder="选填"></label></div><div class="form-actions"><button class="primary" :disabled="busy">{{busy?'正在保存…':'创建标签'}}</button><button type="button" :disabled="busy" @click="cancel">取消</button></div></form>
 <p class="manager-table-hint">左右滑动，查看完整信息与操作</p>
 <div class="manager-table-wrap" tabindex="0" aria-label="标签列表" :aria-busy="loading"><table role="table" class="manager-table tags-table"><caption class="sr-only">标签名称、说明、公开文章数量、状态与编辑</caption><thead role="rowgroup"><tr role="row"><th role="columnheader" scope="col">名称</th><th role="columnheader" scope="col">说明</th><th role="columnheader" scope="col">公开文章</th><th role="columnheader" scope="col">状态</th><th role="columnheader" scope="col">操作</th></tr></thead><tbody role="rowgroup"><tr role="row" v-if="loading"><td role="cell" colspan="5"><div class="manager-loading" role="status">正在载入标签…</div></td></tr><template v-for="row in filtered" :key="row.id"><tr role="row" :class="{'is-editing':editing===String(row.id)}"><td role="cell" class="manager-tag-name"><strong>{{row.name}}</strong></td><td role="cell" class="manager-tag-description">{{row.description||'—'}}</td><td role="cell" class="manager-number">{{row.article_count||0}}</td><td role="cell"><span class="table-status" :class="row.archived?'trashed':'published'">{{row.archived?'已归档':'使用中'}}</span></td><td role="cell"><button class="quiet" :disabled="busy" :aria-expanded="editing===String(row.id)" @click="editing===String(row.id)?cancel():edit(row)">{{editing===String(row.id)?'收起':'编辑'}}</button></td></tr><tr role="row" v-if="editing===String(row.id)" class="tag-edit-row"><td role="cell" colspan="5"><form class="tag-inline-editor" @submit.prevent="save"><div class="tag-edit-fields"><label>名称<input v-model="form.name" data-tag-edit-name required maxlength="100" :disabled="busy"></label><label>说明<input v-model="form.description" maxlength="2000" :disabled="busy" placeholder="选填"></label></div><label class="check"><input v-model="form.archived" type="checkbox" :disabled="busy">归档这个标签</label><p class="muted">归档后不再用于新选择，已有文章的标签关系会保留。</p><div class="form-actions"><button class="primary" :disabled="busy">{{busy?'正在保存…':'保存修改'}}</button><button type="button" :disabled="busy" @click="cancel">取消</button></div></form></td></tr></template><tr role="row" v-if="!loading&&!filtered.length"><td role="cell" colspan="5"><div class="manager-empty"><strong>{{rows.length?'没有匹配的标签':'还没有标签'}}</strong><p>{{rows.length?'调整关键词或状态筛选。':'创建标签，为文章留一条可继续探索的线索。'}}</p></div></td></tr></tbody></table></div><p class="manager-caption">{{filtered.length}} 个标签 · 文章数仅计算当前公开内容</p>
</section></template>
